"""B3 fixed Owner orchestration, ISOLATED_NEW only. Execute after confirmation."""
import base64,fcntl,hashlib,json,os,re,stat,subprocess,sys,time
from pathlib import Path
HOST='iZd7oeikknn1z21sq6ji6zZ'
BASE=Path('/var/lib/xuanjun-p2-isolated-test')
ROOT=BASE/'b3-initialize'
INPUT=BASE/'b3-input-20261020'
LOGS=BASE/'logs/b3-initialize-20261020'
IMAGE='sha256:5341f193a5741b64f2acc63a99dc95910289fcc39ff17dacff373a50e233724d'
PAYLOAD=''
P=json.loads(base64.b64decode(PAYLOAD))
REQUEST_RAW=base64.b64decode(P['request'])
REQUEST=json.loads(REQUEST_RAW)
def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def require(condition, reason):
    if not condition:
        raise RuntimeError(reason)


def directory(path, uid, gid, mode):
    path.mkdir(mode=0o700)
    fd = os.open(str(path), os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        os.fchown(fd, uid, gid)
        os.fchmod(fd, mode)
        os.fsync(fd)
    finally:
        os.close(fd)
    sync(path.parent)


def sync(path):
    fd = os.open(str(path), os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def write(path, raw, uid=0, gid=0, mode=0o600):
    fd = os.open(str(path), os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, mode)
    with os.fdopen(fd, 'wb') as out:
        out.write(raw)
        os.fchown(out.fileno(), uid, gid)
        os.fchmod(out.fileno(), mode)
        out.flush()
        os.fsync(out.fileno())
    sync(path.parent)


def read_file(path):
    fd = os.open(str(path), os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    with os.fdopen(fd, 'rb') as source:
        info = os.fstat(source.fileno())
        require(stat.S_ISREG(info.st_mode), 'NON_REGULAR_EVIDENCE')
        raw = source.read()
    return raw, info


def container_state(name):
    fields = '{"state":{{json .State}},"image":{{json .Image}},"user":{{json .Config.User}},"mounts":{{json .Mounts}},"network":{{json .HostConfig.NetworkMode}},"readonly":{{json .HostConfig.ReadonlyRootfs}},"cap_drop":{{json .HostConfig.CapDrop}},"security_opt":{{json .HostConfig.SecurityOpt}},"memory":{{json .HostConfig.Memory}},"memory_swap":{{json .HostConfig.MemorySwap}},"pids":{{json .HostConfig.PidsLimit}},"cpu_quota":{{json .HostConfig.CpuQuota}},"nano_cpus":{{json .HostConfig.NanoCpus}}}'
    p = subprocess.run(['/bin/docker', 'inspect', '--format', fields, name], stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=15)
    require(p.returncode == 0, 'CONTAINER_INSPECT_FAILED:' + name)
    return json.loads(p.stdout.decode())


def safe_source(path):
    fd=os.open('/',os.O_RDONLY|os.O_DIRECTORY)
    try:
        for part in path.parts[1:-1]:
            child=os.open(part,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW,dir_fd=fd)
            os.close(fd);fd=child
        src=os.open(path.name,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK,dir_fd=fd)
        with os.fdopen(src,'rb') as stream:
            before=os.fstat(stream.fileno())
            require(stat.S_ISREG(before.st_mode) and before.st_size<=4194304,'SOURCE_TYPE_SIZE')
            raw=stream.read(4194305);after=os.fstat(stream.fileno())
            meta=lambda s:(s.st_dev,s.st_ino,s.st_uid,s.st_gid,stat.S_IMODE(s.st_mode),s.st_size,s.st_mtime_ns,s.st_ctime_ns)
            require(meta(before)==meta(after) and len(raw)==before.st_size,'SOURCE_CHANGED_DURING_READ')
            return raw,meta(after)
    finally:os.close(fd)


def originals():
    version=BASE/'artifacts/versions/p2-uk-isolated-20261020--b1-release'
    refs={'MANIFEST.json':(version/'MANIFEST.json','591855b35c820c486ae07bbb91e681b983a3a2310feaedb57ae7c87fc9b66592'),
      'b1-receipt.json':(BASE/'artifacts/.p2_artifacts/receipts/p2-uk-isolated-20261020--b1-release.json','2aa0616f8d9cc57e4dc367198fcb40b1d9cfe88ffa46221273c62cf4ad6e069a')}
    result={}
    for name,(path,pin) in refs.items():
        raw,meta=safe_source(path);require(sha(raw)==pin,'B1_FIXED_SOURCE_SHA:'+name);result[name]=(raw,meta)
    return result

def installed(request):
    rows={}
    for relative,pin in P['expected_files'].items():
        raw,info=read_file(ROOT/relative)
        mode=0o644 if relative.startswith('activation/') else 0o400
        require(raw==base64.b64decode(pin) and (info.st_uid,info.st_gid,stat.S_IMODE(info.st_mode))==(1002,1002,mode),'B3_FILE:'+relative)
    for parent,dirs,files in os.walk(str(ROOT),followlinks=False):
        for name in dirs:require(stat.S_ISDIR(os.lstat(os.path.join(parent,name)).st_mode),'B3_LINK_DIRECTORY')
        for name in files:
            path=Path(parent)/name;raw,info=read_file(path)
            rows[str(path.relative_to(ROOT))]={'sha256':sha(raw),'inode':info.st_ino,'mtime_ns':info.st_mtime_ns,'uid':info.st_uid,'gid':info.st_gid,'mode':stat.S_IMODE(info.st_mode),'size':info.st_size}
    require(not os.path.lexists(str(ROOT/'data/ledger.sqlite3')) and not os.path.lexists(str(ROOT/'run/ledger.sock')),'NO_DB_SOCKET')
    path=ROOT/'commit-receipt.json';raw,info=read_file(path)
    return {'files':rows,'receipt':{'path':str(path),'sha256':sha(raw),'inode':info.st_ino,'mtime_ns':info.st_mtime_ns}},raw

def command(action):
    return ['/bin/docker','run','--interactive','--pull=never','--name=p2-uk-b3-'+action+'-20261020',
      '--cidfile='+str(LOGS/(action+'.cid')),'--hostname='+HOST,'--user=1002:1002','--network=none',
      '--cap-drop=ALL','--security-opt=no-new-privileges','--read-only','--pids-limit=96','--memory=512m','--memory-swap=1g','--log-driver=none',
      '--mount=type=bind,src='+str(INPUT)+',dst=/input,readonly','--mount=type=bind,src='+str(ROOT)+',dst='+str(ROOT),
      '--workdir=/input/tools','--env=PYTHONPATH=/input/tools','--env=PYTHONNOUSERSITE=1','--entrypoint=/usr/bin/python3.11',
      IMAGE,'-B','-S','-m','production.p2_install.initialize',action,'--request-sha256',sha(REQUEST_RAW)]

def main():
    os.umask(0o077)
    require(os.geteuid()==0 and os.uname().nodename.split('.')[0]==HOST,'HOST_IDENTITY')
    for path in (Path('/var'),Path('/var/lib'),BASE,BASE/'state',BASE/'logs'):
        require(stat.S_ISDIR(os.lstat(str(path)).st_mode),'PARENT_DIRECTORY')
    parent=os.lstat(str(BASE));require((parent.st_uid,parent.st_gid,stat.S_IMODE(parent.st_mode))==(0,0,0o700),'BASE_IDENTITY')
    require(not any(os.path.lexists(str(p)) for p in (INPUT,ROOT,LOGS)),'EXISTING_B3_RETAIN_RECONCILE')
    request=REQUEST
    tools={p:base64.b64decode(raw) for p,raw in P['tools'].items()}
    require(all(sha(raw)==P['tool_sha256'][p] for p,raw in tools.items()),'TOOL_SHA')
    prior=originals()
    lock=os.open(str(BASE/'state/.formal-cli.lock'),os.O_RDWR|os.O_CREAT|os.O_NOFOLLOW,0o600)
    try:
        li=os.fstat(lock);require(stat.S_ISREG(li.st_mode) and li.st_uid==0 and stat.S_IMODE(li.st_mode)==0o600,'INSTALL_LOCK')
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        directory(LOGS,0,0,0o700)
        summary={'schema':1,'scope':'ISOLATED_TEST_ONLY','origin':'ISOLATED_NEW','status':'NOT_EXECUTED','calls':[],
          'request_sha256':sha(REQUEST_RAW),'request':request,'full_b3_complete':False,'production_activated':False,
          'source_sha256':sha(Path(__file__).read_bytes()),'tool_sha256':P['tool_sha256'],'retained_paths':[str(ROOT),str(INPUT),str(LOGS)]}
        try:
            write(LOGS/'owner-script.py',Path(__file__).read_bytes());write(LOGS/'request.json',REQUEST_RAW)
            directory(INPUT,0,1002,0o550);directory(INPUT/'sources',0,1002,0o550)
            for name,(raw,meta) in prior.items():write(INPUT/'sources'/name,raw,0,1002,0o440)
            write(INPUT/'request.json',REQUEST_RAW,0,1002,0o440)
            for relative,raw in sorted(tools.items()):
                path=INPUT/'tools'/relative
                ancestors=[];current=path.parent
                while current!=INPUT and not current.exists():ancestors.append(current);current=current.parent
                for folder in reversed(ancestors):directory(folder,0,1002,0o550)
                write(path,raw,0,1002,0o440)
            directory(ROOT,1002,1002,0o700)
            for leaf in ('data','run'):directory(ROOT/leaf,1002,1002,0o700)
            baseline = None
            for action in ('execute', 'inspect', 'recover'):
                name = 'p2-uk-b3-' + action + '-20261020'
                args = command(action)
                call = {'action': action, 'argv': args, 'started_utc': int(time.time()), 'exit_code': None}
                summary['calls'].append(call)
                with (LOGS / (action + '-stdout.json')).open('xb') as out, (LOGS / (action + '-stderr.log')).open('xb') as err:
                    try:
                        p = subprocess.run(args, input=REQUEST_RAW, stdout=out, stderr=err, timeout=120)
                        call['exit_code'] = p.returncode
                    except subprocess.TimeoutExpired:
                        call['timeout'] = True
                        if (LOGS / (action + '.cid')).is_file():
                            cid = (LOGS / (action + '.cid')).read_text().strip()
                            require(re.fullmatch('[0-9a-f]{64}', cid), 'INVALID_OWN_CONTAINER_ID')
                            stopped = subprocess.run(['/bin/docker', 'stop', '--time=3', cid], stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=15)
                            call['stop_exit'] = stopped.returncode
                        else:
                            call['stop_result'] = 'NO_CREATED_CID_NO_UNKNOWN_CONTAINER_STOP'
                    finally:
                        out.flush(); os.fsync(out.fileno())
                        err.flush(); os.fsync(err.fileno())
                call['ended_utc'] = int(time.time())
                cid = (LOGS / (action + '.cid')).read_text().strip()
                require(re.fullmatch('[0-9a-f]{64}', cid), 'INVALID_OWN_CONTAINER_ID')
                call['container_id'] = cid
                state = container_state(cid)
                call['container'] = state
                write(LOGS / (action + '-container.json'), json.dumps(state, sort_keys=True, indent=2).encode())
                require(state['state']['Running'] is False, 'CONTAINER_STILL_RUNNING_RETAIN_STATE')
                require(state['image'] == IMAGE and state['user'] == '1002:1002'
                        and state['network'] == 'none' and state['readonly'] is True
                        and 'ALL' in state['cap_drop']
                        and any(x.startswith('no-new-privileges') for x in state['security_opt'])
                        and state['memory'] == 536870912 and state['memory_swap'] == 1073741824
                        and state['pids'] == 96 and state['cpu_quota'] == 0 and state['nano_cpus'] == 0,
                        'ACTUAL_CONTAINER_BOUNDARY_MISMATCH')
                mounts = {(x['Source'], x['Destination'], x['RW'], x['Type']) for x in state['mounts']}
                require(mounts == {(str(INPUT), '/input', False, 'bind'),
                                   (str(ROOT), str(ROOT), True, 'bind')}, 'ACTUAL_MOUNT_MISMATCH')
                raw, unused = read_file(LOGS / (action + '-stdout.json'))
                stderr, unused = read_file(LOGS / (action + '-stderr.log'))
                call['stdout'] = raw.decode('utf-8', 'replace')
                call['stderr'] = stderr.decode('utf-8', 'replace')
                call['stdout_sha256'] = sha(raw)
                call['stderr_sha256'] = sha(stderr)
                require(call['exit_code'] == 0, 'CLI_FAILED_RETAIN_STATE:' + action)
                response = json.loads(raw.decode())
                call['response'] = response
                require(response['status'] == 'COMMITTED', 'NOT_COMMITTED:' + action)
                for key in ('schema','scope','installation_id','batch_id','attempt_id'):
                    require(response[key] == request[key], 'RESPONSE_IDENTITY:' + key)
                require(originals() == prior, 'B1_SOURCE_CHANGED')
                observed, receipt_raw = installed(request)
                require(response['receipt'] == {k: observed['receipt'][k] for k in ('path','sha256')}, 'RECEIPT_REFERENCE')
                call['observed'] = observed
                if baseline is None:
                    baseline = observed
                    write(LOGS / 'original-commit-receipt.json', receipt_raw)
                else:
                    require(observed == baseline, 'COMMITTED_BYTES_OR_METADATA_CHANGED:' + action)
                write(LOGS / (action + '-result.json'), json.dumps(call, sort_keys=True, indent=2).encode())
            require(originals()==prior,'B1_SOURCE_CHANGED')
            after=os.lstat(str(BASE));require((after.st_uid,after.st_gid,stat.S_IMODE(after.st_mode),after.st_ino)==(0,0,0o700,parent.st_ino),'BASE_CHANGED')
            summary['status']='B3_NEW_INITIALIZATION_SUBCHECKPOINT_PASS'
        except Exception as exc:
            summary['status']='FAILED_RETAINED';summary['error']={'type':type(exc).__name__,'detail':str(exc)}
        finally:
            summary['ended_utc']=int(time.time());write(LOGS/'summary.json',json.dumps(summary,sort_keys=True,indent=2).encode())
            print(json.dumps(summary,sort_keys=True,indent=2));print('RETAINED_SUMMARY='+str(LOGS/'summary.json'))
        return 0 if summary['status']=='B3_NEW_INITIALIZATION_SUBCHECKPOINT_PASS' else 2
    finally:os.close(lock)

if __name__=='__main__':
    try:sys.exit(main())
    except Exception as exc:
        print(json.dumps({'status':'HOLD_RETAIN_STATE','scope':'ISOLATED_TEST_ONLY','error':str(exc),'production_activated':False},sort_keys=True));sys.exit(2)
